What's interesting, requiring HTTP/2 causes chunks to contain repeated data. Such a script:

```
import http2 from 'node:http2'

async function makeHttp2Request(graphQuery, requestContext) {
    const { access_token, username } =
        requestContext.session.get('sessionKey') || {}
    const client = http2.connect('https://URI/')

    const req = client.request({
        ':method': 'POST',
        ':path': 'PATH',
        'Content-Type': 'application/json',
        Cookie: `_session=${JSON.stringify({ access_token, username })}`,
    })

    // Send body
    req.write(JSON.stringify(graphQuery))
    req.end()

    let data = ''
    req.on('data', (chunk) => {
        data += chunk
    })

    req.on('end', async () => {
        console.log('Raw Response:', data)

        try {
            const parsed = JSON.parse(data)

            console.log('WRITING JSON')
            await fs.writeFile(
                'response-object.json',
                JSON.stringify(parsed, null, 2)
            )
        } catch (e) {
            console.log('WRITING TXT')
            textResponses += 1

            await fs.writeFile('response-string.txt', data)
        }

        client.close() // Important!
    })

    req.on('error', (err) => {
        console.error('HTTP2 Request Error:', err)
        client.close()
    })
}
```

