def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}
    severity = {"pass": 0, "skip": 1, "fail": 2}

    def update_result(name: str, status: str) -> None:
        if not name:
            return
        prev = results.get(name)
        if prev is None or severity[status] > severity[prev]:
            results[name] = status

    def local(tag: str) -> str:
        return tag.rsplit("}", 1)[-1] if tag else tag

    def parse_xml_string(xml_text: str) -> None:
        xml_text = xml_text.strip()
        if not xml_text:
            return
        # Strip invalid XML control chars
        xml_text_clean = re.sub(r"[\x00-\x08\x0B\x0C\x0E-\x1F]", "", xml_text)
        roots = []
        try:
            roots.append(ET.fromstring(xml_text_clean))
        except ET.ParseError:
            # Try wrapping in root for multiple top-level elements
            try:
                wrapped = f"<root>{xml_text_clean}</root>"
                roots.append(ET.fromstring(wrapped))
            except ET.ParseError:
                return
        for root in roots:
            for testcase in root.iter():
                if local(testcase.tag) != "testcase":
                    continue
                name = testcase.get("name")
                classname = testcase.get("classname") or testcase.get("class")
                full_name = None
                if classname and name:
                    full_name = f"{classname}::{name}"
                elif name:
                    full_name = name
                elif classname:
                    full_name = classname

                status = "pass"
                for child in testcase.iter():
                    tag = local(child.tag)
                    if tag in ("failure", "error"):
                        status = "fail"
                        break
                    if tag == "skipped":
                        status = "skip"
                update_result(full_name, status)

    # Collect XML chunks
    xml_chunks = []
    if "<?xml" in log:
        parts = re.split(r"(?=<\?xml)", log)
        for part in parts:
            if "<testsuite" in part or "<testsuites" in part:
                xml_chunks.append(part)
    # Also add any standalone testsuite blocks
    xml_chunks.extend(re.findall(r"<testsuite\b.*?</testsuite>", log, flags=re.DOTALL))
    xml_chunks.extend(re.findall(r"<testsuites\b.*?</testsuites>", log, flags=re.DOTALL))

    for chunk in xml_chunks:
        parse_xml_string(chunk)

    # Fallback: parse common text-based outputs
    for line in log.splitlines():
        line = line.strip()
        if not line:
            continue

        # pytest style
        m = re.match(r"^(?P<name>\S+::\S+)\s+(?P<status>PASSED|FAILED|SKIPPED|ERROR)$", line)
        if m:
            status = m.group("status")
            update_result(m.group("name"), "fail" if status in ("FAILED", "ERROR") else status.lower())
            continue

        # unittest style
        m = re.match(r"^(?P<name>\S+)\s+\.\.\.\s+(?P<status>ok|FAIL|ERROR|SKIP(?:PED)?)$", line, re.IGNORECASE)
        if m:
            status = m.group("status").lower()
            if status in ("fail", "error"):
                update_result(m.group("name"), "fail")
            elif status.startswith("skip"):
                update_result(m.group("name"), "skip")
            else:
                update_result(m.group("name"), "pass")
            continue

        # go test style
        m = re.match(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", line)
        if m:
            status = m.group(1)
            update_result(m.group(2), "fail" if status == "FAIL" else ("skip" if status == "SKIP" else "pass"))
            continue

        # jest style symbols
        m = re.match(r"^[\s\|]*[✓✔]\s+(?P<name>.+)$", line)
        if m:
            update_result(m.group("name").strip(), "pass")
            continue
        m = re.match(r"^[\s\|]*[✕✖]\s+(?P<name>.+)$", line)
        if m:
            update_result(m.group("name").strip(), "fail")
            continue
        m = re.match(r"^[\s\|]*[○◌]\s+(?P<name>.+)$", line)
        if m:
            update_result(m.group("name").strip(), "skip")
            continue

    return results
